// Bland-Altman analysis of the agreement of two methods of measurement: the mean difference, the limits of agreement
// d̄ ± two·s and their confidence intervals, as BlandAltmanLeh's bland.altman.stats, with the exact interval of the
// limits as an alternative.
//
// Written for rStats.js from oracle/methodcomparison-behaviour.md (section 1) and the published methods (no R or
// package code was read):
// - Bland JM, Altman DG (1986), Statistical methods for assessing agreement between two methods of clinical
//   measurement, Lancet i:307-310: the limits d̄ ± 1.96 s, the t interval of the mean difference, and the standard
//   error sqrt(3 s²/n) of a limit (an approximation of s² (1/n + z²/(2(n - 1))) for z = 1.96 and large n), used with
//   t quantiles ("package", BlandAltmanLeh's interval).
// - Carkeet A (2015), Exact parametric confidence intervals for Bland-Altman limits of agreement, Optometry and Vision
//   Science 92:e71-e80: sqrt(n) (μ + zσ - d̄)/s has the noncentral t distribution with n - 1 degrees of freedom and
//   noncentrality z sqrt(n), so the exact interval of the upper limit is d̄ + s q/sqrt(n) at the quantiles q of that
//   distribution, and that of the lower limit its mirror image ("exact").
//
// The differences are scaled by a power of 2 of their own (src/internal/summary.ts), so that the squares of the
// standard deviation neither over- nor underflow; results with units are scaled back at the end (exact), so in the
// ordinary range they are those of the unscaled formulas.
import { qnt1 } from "../distributions/nt.js";
import { qt1 } from "../distributions/t.js";
import { ldexp, mean, scaleToUnit, standardDeviation } from "../internal/summary.js";
import { reported } from "../internal/warnings.js";
import { matchChoice } from "./power.js";
import { checkConfLevel } from "./types.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const BLAND_ALTMAN_KEYS = ["two", "mode", "confLevel", "ciMethod"];
const CI_METHODS = ["package", "exact"];
/** t s, with 0 for s = 0 (identical methods: the intervals are points, also at the level 1 where t is infinite) */
const times = (t, s) => (s === 0 ? 0 : t * s);
/**
 * Bland-Altman analysis of two methods of measurement: the mean difference, the limits of agreement and their
 * confidence intervals. Equivalent to `BlandAltmanLeh::bland.altman.stats()` in R.
 *
 * With d the differences of the complete pairs (pairs with `NaN` in either sample are dropped), d̄ their mean and s
 * their standard deviation, the limits of agreement are `d̄ ± two s`. The mean difference has the t interval `d̄ ± t
 * s/sqrt(n)` with t quantiles on n - 1 degrees of freedom. The interval of each limit is, by default, BlandAltmanLeh's
 * `limit ± t sqrt(3 s²/n)` (Bland and Altman 1986); `ciMethod: "exact"` gives the exact interval (Carkeet 2015):
 * `d̄ + s q/sqrt(n)` for the upper limit with q the quantiles (1 ∓ confLevel)/2 of the noncentral t distribution with
 * n - 1 degrees of freedom and noncentrality `two sqrt(n)`, and its mirror image for the lower limit.
 *
 * Unlike R, fewer than 2 complete pairs, infinite values and a level outside [0, 1] are errors (R gives NA or NaN
 * limits); `confLevel` 0 gives intervals of width 0 and 1 infinite ones, as R. Identical methods (s = 0) give every
 * limit and interval equal to d̄.
 *
 * @param x Measurements by the first method.
 * @param y Measurements by the second method, paired with `x`.
 * @param options See {@link BlandAltmanOptions}.
 * @returns See {@link BlandAltmanResult}.
 * @throws TypeError if `x` and `y` differ in length; RangeError for fewer than 2 complete pairs, infinite values, a
 *   `two` that is not positive and finite, a `mode` other than 1 or 2, a level outside [0, 1] or an unknown
 *   `ciMethod`.
 *
 * @example
 * ```ts
 * const x = [10.1, 12.3, 9.8, 15.2, 11.1, 13.4, 14.8, 9.9, 12.0, 16.3];
 * const y = [10.6, 12.0, 10.4, 15.9, 11.0, 14.1, 15.3, 10.3, 12.9, 16.8];
 * const r = blandAltman(x, y);
 * r.meanDiff;          // -0.44000000000000006
 * [r.lowerLimit, r.upperLimit]; // [-1.1628122854517629, 0.28281228545176262]
 * r.upperLimitConfInt; // [-0.17412106328886995, 0.73974563419239514]
 * blandAltman(x, y, { ciMethod: "exact" }).upperLimitConfInt; // [-0.011029811389107025, 0.961726537758047]
 * ```
 *
 * @category Agreement, reliability and factor analysis
 */
export function blandAltman(x, y, options = {}) {
    checkOptions(options, BLAND_ALTMAN_KEYS, "blandAltman"); // generated: option-keys.mjs
    if (x.length !== y.length)
        throw new TypeError("'x' and 'y' must have the same length");
    const two = options.two ?? 1.96;
    if (!(typeof two === "number" && two > 0 && two < Infinity))
        throw new RangeError("'two' must be a positive number");
    const mode = options.mode ?? 1;
    if (mode !== 1 && mode !== 2)
        throw new RangeError("'mode' must be 1 or 2");
    const confLevel = options.confLevel ?? 0.95;
    checkConfLevel(confLevel);
    const ciMethod = matchChoice(options.ciMethod, CI_METHODS);
    // the complete pairs (NaN counts as missing, as R's na.omit)
    const a = [];
    const b = [];
    for (let i = 0; i < x.length; i++) {
        const u = x[i];
        const v = y[i];
        if (typeof u !== "number" || typeof v !== "number")
            throw new TypeError("'x' and 'y' must be numeric");
        if (Number.isNaN(u) || Number.isNaN(v))
            continue;
        if (!Number.isFinite(u) || !Number.isFinite(v))
            throw new RangeError("'x' and 'y' must not contain infinite values");
        a.push(u);
        b.push(v);
    }
    const n = a.length;
    if (n < 2)
        throw new RangeError("fewer than 2 complete pairs");
    const [first, second] = mode === 1 ? [a, b] : [b, a];
    // (x + y)/2 as R; x/2 + y/2 only where the sum overflows
    const means = a.map((u, i) => {
        const m = (u + b[i]) / 2;
        return Number.isFinite(m) ? m : u / 2 + b[i] / 2;
    });
    const diffs = first.map((u, i) => u - second[i]);
    // everything below in the coordinates 2^-k of the differences themselves (not of the data, where small differences
    // beside a large pair would underflow), scaled back by ldexp at the end; the differences of the halves (k + 1) only
    // where a difference overflows
    const half = !diffs.every(Number.isFinite);
    const { groups, k: kd } = scaleToUnit([half ? first.map((u, i) => u / 2 - second[i] / 2) : diffs]);
    const d = groups[0];
    const k = kd + (half ? 1 : 0);
    const m = mean(d);
    const s = standardDeviation(d);
    const crit = two * s;
    const lower = m - crit;
    const upper = m + crit;
    const df = n - 1;
    const tail = (1 - confLevel) / 2;
    const t1 = qt1(tail, df, true, false);
    // (rule 10: the upper tail itself for a tail below 1e-8)
    const t2 = tail < 1e-8 ? qt1(tail, df, false, false) : qt1((confLevel + 1) / 2, df, true, false);
    const meanDiffConfInt = [m + times(t1, s) / Math.sqrt(n), m + times(t2, s) / Math.sqrt(n)];
    let lowerLimitConfInt;
    let upperLimitConfInt;
    if (ciMethod === "package") {
        // (s sqrt(3/n) where 3 s²/n would leave the normal range)
        const v3 = (3 * s * s) / n;
        const se = v3 >= 2 ** -1022 || v3 === 0 ? Math.sqrt(v3) : s * Math.sqrt(3 / n);
        lowerLimitConfInt = [lower + times(t1, se), lower + times(t2, se)];
        upperLimitConfInt = [upper + times(t1, se), upper + times(t2, se)];
    }
    else {
        // Carkeet (2015): the quantiles of the noncentral t with noncentrality two sqrt(n), each from its own tail
        const ncp = two * Math.sqrt(n);
        const qLo = qnt1(tail, df, ncp, true, false) / Math.sqrt(n);
        const qHi = qnt1(tail, df, ncp, false, false) / Math.sqrt(n);
        lowerLimitConfInt = [m - times(qHi, s), m - times(qLo, s)];
        upperLimitConfInt = [m + times(qLo, s), m + times(qHi, s)];
    }
    const back = (v) => ldexp(v, k);
    const pair = (p) => [back(p[0]), back(p[1])];
    return reported("blandAltman", {
        means,
        diffs,
        n,
        meanDiff: back(m),
        lowerLimit: back(lower),
        upperLimit: back(upper),
        criticalDiff: back(crit),
        meanDiffConfInt: pair(meanDiffConfInt),
        lowerLimitConfInt: pair(lowerLimitConfInt),
        upperLimitConfInt: pair(upperLimitConfInt),
        confLevel,
        two,
        mode,
        ciMethod,
        warnings: [],
    });
}
